  ('zcrm_5797994000002232013', 'Teiko.bio', 'Teiko.bio', 'Rosemary Moyo', 'Carlos Medina', 'Teiko.bio is an immune profiling platform that enables clinicians to make informed decisions around patient response.', 'HV STEM', 'Healthcare', 'Spring 2025', NULL, 'Reached Out', 'Rosemary Moyo', 'Rejected', NULL, NULL, NULL, '2025-02-03 07:18:16', '2025-08-26 07:45:14', '2025-08-26 07:45:14'),
  ('zcrm_5797994000002232032', 'EvoEndo', NULL, 'Aaditya Jain', 'Naim Farah', 'The EvoEndo System introduces a sedation-free, lower-risk, cost-effective alternative to traditional endoscopy. We incorporate a single-use, ultra-slim, flexible scope with four-way steering, a portable controller with advanced image quality, and a virtual reality-based system for patient distraction.', 'HV STEM', 'Healthcare', 'Spring 2025', 'Pitchbook', 'Reached Out', 'Aadi Jain', 'Rejected', NULL, NULL, NULL, '2025-02-03 14:12:12', '2025-08-26 07:43:40', '2025-08-26 07:43:40'),
  ('zcrm_5797994000002232052', 'UNCAGED Innovations', NULL, 'Aaditya Jain', 'Stephanie Downs', 'Uncaged Innovations develops next-generation materials to recreate bovine and exotic leather through advancements in materials chemistry and digital manufacturing, providing businesses from luxury fashion to automotives with an alternative to animal skin and sustainable and ethical services.', 'HV STEM', 'Healthcare;Sustainability', 'Spring 2025', NULL, 'Reached Out', 'Aadi Jain', 'Rejected', NULL, NULL, NULL, '2025-02-03 15:49:56', '2025-08-26 07:45:14', '2025-08-26 07:45:14'),
  ('zcrm_5797994000002232069', 'Diakonos Oncology', NULL, 'Aaditya Jain', 'Anthony Baldor', 'Diakonos Oncology is pioneering cancer treatment with DOC1021, an FDA Fast Track-designated "double-loaded" dendritic cell therapy for glioblastoma (GBM) and pancreatic cancer (PDAC). This personalized, autologous therapy has shown exceptional safety and efficacy, achieving an 88% 12-month survival rate in unmethylated GBM Phase I trials, with 38% of patients still alive after 18–29 months. With a Phase II trial launching in Q1 2025 at top GBM centers nationwide, Diakonos is reshaping outcomes for patients with the most challenging cancers.', 'HV STEM', 'Healthcare', 'Spring 2025', NULL, 'Reached Out', 'Aadi Jain', 'Rejected', NULL, NULL, NULL, '2025-02-03 16:11:41', '2025-08-26 07:45:14', '2025-08-26 07:45:14'),
  ('zcrm_5797994000002232086', 'Kiwi Biosciences', NULL, 'Aaditya Jain', 'Shalaka Samant', 'The first solution to target FODMAPs directly so you can stop avoiding your favorite foods. FODZYME® is a novel patent-pending enzyme supplement that breaks down the FODMAPs fructan, galacto-oligosaccharides, and lactose, common gut symptom triggers for people with IBS.', 'HV STEM', 'Healthcare', 'Spring 2025', NULL, 'Reached Out', 'Aadi Jain', 'Rejected', NULL, NULL, NULL, '2025-02-03 16:57:06', '2025-08-26 07:45:14', '2025-08-26 07:45:14'),
  ('zcrm_5797994000002233001', 'Chai Discovery', 'Chai Discovery', 'Rosemary Moyo', 'Joshua Meier', 'Chai Discovery creates Chai-1, a multi-modal foundation model designed for predicting molecular structures relevant to drug discovery. The model facilitates the unified prediction of proteins, small molecules, and nucleic acids, and is available for free for commercial applications. By enabling accurate predictions without the need for multiplesequence alignments, Chai-1 advances the capabilities of molecular modeling in the life sciences.', 'HV STEM', 'Healthcare', 'Spring 2025', NULL, 'Reached Out', 'Rosemary Moyo', 'Rejected', NULL, NULL, NULL, '2025-02-03 05:37:42', '2025-02-28 14:29:01', '2025-02-28 14:29:01'),
  ('zcrm_5797994000002235001', 'Flow Medical', 'Flow Medical', 'Rosemary Moyo', 'Jennifer Fried', 'Flow Medical offers multi-function catheters to aid in the diagnosis and treatment of venous thromboembolic illness.', 'HV STEM', 'Healthcare', 'Spring 2025', NULL, 'Reached Out', 'Rosemary Moyo', 'Rejected', NULL, NULL, NULL, '2025-02-03 05:44:58', '2025-02-28 14:35:19', '2025-02-28 14:35:19'),
  ('zcrm_5797994000002235027', 'Aarvik Therapeutics', 'Aarvik Therapeutics', 'Rosemary Moyo', 'Sachdev Sidhu', 'Aarvik Therapeutics combines a unique, proprietary modular platform with multiple target mechanisms to develop novel molecules with an improved therapeutic index for oncology targets. Backed by the extensive scientific research, development, and investment expertise of its founders and Board members, Aarvik Therapeutics is applying its vision andpassion to create transformational benefits for cancer patients.', 'HV STEM', 'Healthcare', 'Spring 2025', NULL, 'Reached Out', 'Rosemary Moyo', 'Rejected', NULL, NULL, NULL, '2025-02-03 07:29:59', '2025-08-26 07:45:14', '2025-08-26 07:45:14'),
  ('zcrm_5797994000002235041', 'Systemic Bio', 'Systemic Bio', 'Rosemary Moyo', 'Taci Pereira', 'Systemic Bio creates bioprinted organs-on-chips for drug discovery and development. Its proprietary platform is built with production-level 3D Systems technology, which has at least 10x greater build volume and up to 10x higher resolution than commercially available technologies.', 'HV STEM', 'Healthcare', 'Spring 2025', NULL, 'Reached Out', 'Rosemary Moyo', 'Rejected', NULL, NULL, NULL, '2025-02-03 07:55:05', '2025-08-26 07:45:14', '2025-08-26 07:45:14'),
