  ('zcrm_5797994000002246636', 'Trilobio', 'Trilobio', 'Kishan Angadi', 'Roya Naieni', 'Trilobio was created to improve synthetic biology and life science research processes by building robotic lab automation modules coupled with an "app store" to package and distribute lab protocols as code. The goal is to deploy fully automated labs that dramatically improve data quality and reproducibility.', 'HV STEM', 'Healthcare', 'Spring 2025', NULL, 'Reached Out', 'Kishan Angadi', 'Rejected', NULL, NULL, NULL, '2025-02-04 17:05:29', '2025-05-14 06:34:20', '2025-05-14 06:34:20'),
  ('zcrm_5797994000002246660', 'Crop Diagnostix', 'Crop Diagnostix', 'Kishan Angadi', 'Brandon Chi', 'Their breakthrough technology uses RNA sequencing and AI to decode the plant’s language, providing actionable insights for agronomists and verifying product performance for input manufacturers.', 'HV STEM', 'Healthcare', 'Spring 2025', NULL, 'Reached Out', 'Kishan Angadi', 'Rejected', NULL, NULL, NULL, '2025-02-04 17:16:43', '2025-05-14 06:34:12', '2025-05-14 06:34:12'),
