  ('zcrm_5797994000002246708', 'Via Scientific', 'Via Scientific', 'Kishan Angadi', 'Alper Kucukural', 'Via Scientific to help scientists and bioinformaticians generate novel science that improves the world. It was founded in 2022.', 'HV STEM', 'Healthcare', 'Spring 2025', NULL, 'Reached Out', 'Kishan Angadi', 'Rejected', NULL, NULL, NULL, '2025-02-04 17:57:07', '2025-05-14 06:34:08', '2025-05-14 06:34:08'),
